MOD = 10**9 + 7


def _divisor_count(m: int) -> int:
    d, i = 0, 1
    while i * i <= m:
        if m % i == 0:
            d += 1 if i * i == m else 2
        i += 1
    return d


def toGoodArrays(N: int, M: int, K: int) -> int:
    """长度为 N、元素取 1..M 的数组中，恰有 K 个 i 满足 A[i]*A[i+1]==M 的个数。"""
    D = _divisor_count(M)
    L = K + 1  # 多项式只保留 z^0..z^K，z 标记一次“好相邻对”

    def pmul(a, b):
        r = [0] * L
        for i, x in enumerate(a):
            if x:
                for j in range(L - i):
                    r[i + j] = (r[i + j] + x * b[j]) % MOD
        return r

    def padd(a, b):
        return [(x + y) % MOD for x, y in zip(a, b)]

    def const(c):
        return [c % MOD] + [0] * K

    def mmul(X, Y):
        return [[padd(pmul(X[i][0], Y[0][j]), pmul(X[i][1], Y[1][j])) for j in range(2)] for i in range(2)]

    # 状态 0：当前元素是 M 的约数；状态 1：不是
    # 约数 d 的下一个数：恰好 M/d 一个形成好对（z），其余 D-1 个约数、M-D 个非约数都不形成
    z_plus = const(D - 1)
    if K >= 1:
        z_plus[1] = 1
    T = [[z_plus, const(M - D)], [const(D), const(M - D)]]
    R = [[const(1), const(0)], [const(0), const(1)]]
    e = N - 1
    while e:
        if e & 1:
            R = mmul(R, T)
        T = mmul(T, T)
        e >>= 1
    start = [D, M - D]  # 第一个元素
    ans = 0
    for i in range(2):
        for j in range(2):
            ans += start[i] * R[i][j][K]
    return ans % MOD


def _brute(N, M, K):
    from itertools import product
    return sum(
        sum(a[i] * a[i + 1] == M for i in range(N - 1)) == K
        for a in product(range(1, M + 1), repeat=N)
    )


if __name__ == "__main__":
    assert toGoodArrays(2, 3, 0) == 7
    assert toGoodArrays(2, 3, 1) == 2
    assert toGoodArrays(5, 10, 2) == 1368
    for n, m, k in [(3, 4, 1), (4, 6, 2), (3, 12, 0), (4, 4, 3)]:
        assert toGoodArrays(n, m, k) == _brute(n, m, k)
    toGoodArrays(10**9, 735134400, 50)  # 最坏规模也能很快跑完
    print("ok")
